  user_id?: string;
  name: string;
  rollNo: string;
  pagesInfo: string;
  missingPagesWarning?: string;
  status: 'Manual Reviewed' | 'Need to Check' | 'AI Evaluated' | 'Not Evaluated' | 'Completed' | 'evaluated' | 'Evaluating...' | 'Failed';
  marks: string;
