  // ─── Filter Cascade Loading Logic ───
  initFilterCascade(): void {
    if (this.isSuperAdmin) {
      this.loadInstitutes();
    } else if (this.loggedInstituteId) {
      this.selectedInstitute = this.loggedInstituteId;
      this.onInstituteSelected(this.loggedInstituteId);
    }
  }

  loadInstitutes(): void {
    this.http.get<any>(`${API_BASE}/get-institute-list`).subscribe({
      next: (res) => {
        const data = res?.data || res || [];
        this.institutes = Array.isArray(data) ? data : [];
        const savedInst = sessionStorage.getItem('test_eval_institute');
        const instToSelect = this.selectedInstitute || savedInst || '';
        if (instToSelect && this.institutes.some(i => String(i.institute_id) === String(instToSelect))) {
          this.selectedInstitute = instToSelect;
          this.onInstituteSelected(this.selectedInstitute);
        } else {
          this.selectedInstitute = '';
          this.resetAllDependentDropdowns();
        }
      },
      error: (err) => {
        console.error('Failed to load institutes:', err);
      }
    });
  }

  onInstituteChange(instituteId: string): void {
    this.selectedInstitute = instituteId;
    if (instituteId) {
      sessionStorage.setItem('test_eval_institute', instituteId);
      this.onInstituteSelected(instituteId);
    } else {
      sessionStorage.removeItem('test_eval_institute');
      this.resetAllDependentDropdowns();
    }
  }

  onInstituteSelected(instituteId: string): void {
    if (!instituteId) {
      this.resetAllDependentDropdowns();
      return;
    }

    const isEvaluating =
      this.currentView === 'evaluate' ||
      (typeof sessionStorage !== 'undefined' && !!sessionStorage.getItem('test_eval_user_id'));
    const hasActiveExam =
      !!this.selectedExamId ||
      (typeof sessionStorage !== 'undefined' && !!sessionStorage.getItem('test_eval_exam_id'));

    if (!isEvaluating && !hasActiveExam) {
      // Reset all dependent filters when manually switching institute in list mode
      this.selectedClass = '';
      this.selectedSection = '';
      this.selectedSubject = '';
      this.selectedExamId = '';
      sessionStorage.removeItem('test_eval_class');
      sessionStorage.removeItem('test_eval_section');
      sessionStorage.removeItem('test_eval_subject');
      this.testList = [];
      this.allPublishedExams = [];
      this.allInstituteTeams = [];
      this.students = [];
      this.filteredStudents = [];
      this.resetTestDetails();
    }

    // Load dependent masters for this institute
    this.loadDepartments(instituteId);
    this.loadTeams(instituteId);
    this.loadSubjects(instituteId);
    this.loadPublishedExams(instituteId);
  }

  openFiltersOverlay(): void {
    if (!this.filtersBtn) return;
    if (this.filtersOverlayRef) {
      try {
        this.filtersOverlayRef.dispose();
      } catch (e) { }
      this.filtersOverlayRef = null;
    }

    this.instituteFilterSearch = '';
    this.deptFilterSearch = '';
    this.teamFilterSearch = '';
    this.subjectFilterSearch = '';
    this.testFilterSearch = '';

    const targetEl =
      this.filtersBtn?.nativeElement ||
      (this.filtersBtn as any)?._elementRef?.nativeElement ||
      this.filtersBtn;

    const positionStrategy = this.overlay
      .position()
      .flexibleConnectedTo(targetEl)
      .withPositions([
        { originX: 'end', originY: 'bottom', overlayX: 'end', overlayY: 'top', offsetY: 8 },
        { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 8 },
      ])
      .withPush(true);

    this.filtersOverlayRef = this.overlay.create({
      positionStrategy,
      hasBackdrop: true,
      backdropClass: 'cdk-overlay-transparent-backdrop',
      scrollStrategy: this.overlay.scrollStrategies.reposition(),
    });
    this.filtersOverlayRef.backdropClick().subscribe(() => this.closeFiltersOverlay());
    this.filtersOverlayRef.keydownEvents().subscribe((ev: any) => {
      if (ev.key === 'Escape') this.closeFiltersOverlay();
    });

    const portal = new TemplatePortal(this.filtersPanelTpl, this.vcr);
    this.filtersOverlayRef.attach(portal);
  }

  closeFiltersOverlay(): void {
    if (this.filtersOverlayRef) {
      try {
        this.filtersOverlayRef.dispose();
      } catch (e) { }
      this.filtersOverlayRef = null;
    }
  }

  private isFilterSelected(value: string | null | undefined): boolean {
    return !!value && value !== 'ALL';
  }

  private areMandatoryFiltersSelected(): boolean {
    return (
      (!this.isSuperAdmin || !!this.selectedInstitute) &&
      this.isFilterSelected(this.selectedClass) &&
      this.isFilterSelected(this.selectedSection) &&
      this.isFilterSelected(this.selectedSubject)
    );
  }

  applyFiltersPanel(): void {
    if (this.isSuperAdmin && !this.selectedInstitute) {
      notify('Please select an Institute.', 'error');
      return;
    }
    if (!this.isFilterSelected(this.selectedClass)) {
      notify(`Please select a ${this.terminology.deptLabel}.`, 'error');
      return;
    }
    if (!this.isFilterSelected(this.selectedSection)) {
      notify(`Please select a ${this.terminology.teamLabel}.`, 'error');
      return;
    }
    if (!this.isFilterSelected(this.selectedSubject)) {
      notify('Please select a Subject.', 'error');
      return;
    }
    if (!this.selectedExamId) {
      notify('Please select a Test.', 'error');
      return;
    }
    this.closeFiltersOverlay();
    this.applyExamFilters();
    this.filterStudents();
  }

  resetFiltersAndReload(): void {
    this.instituteFilterSearch = '';
    this.deptFilterSearch = '';
    this.teamFilterSearch = '';
    this.subjectFilterSearch = '';
    this.testFilterSearch = '';
    this.clearAppliedFilters();
    this.closeFiltersOverlay();
  }

  stopFilterSearchEvent(event: Event): void {
    event.stopPropagation();
  }

